function statusLabel(status: string) { return status.replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, c => c.toUpperCase()) }
function StatusBadge({ status }: { status: string }) {
  const cls = status.toLowerCase().replaceAll('_', '-')
  return <span className={`status status-${cls}`}><span className="status-dot" />{statusLabel(status)}</span>
}
function DemoPill() { return <span className="demo-pill"><span /> Demo data</span> }
function App() {
  const location = useLocation()
  const [mobileOpen, setMobileOpen] = useState(false)
  const [notice, setNotice] = useState('')
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    try { return localStorage.getItem('city-connect-theme') === 'dark' ? 'dark' : 'light' } catch { return 'light' }
  })
  useEffect(() => {
    try { localStorage.setItem('city-connect-theme', theme) } catch { /* Theme still works for this session. */ }
  }, [theme])
  const toggleTheme = () => setTheme(current => current === 'light' ? 'dark' : 'light')
  const path = location.pathname
  const isDashboard = path === '/unauthorized' || path.startsWith('/citizen') || path.startsWith('/ward') || path.startsWith('/department') || path.startsWith('/mayor') || path.startsWith('/admin') || path === '/notifications'
  const page = routes.find(r => r.path === path || (r.path.includes(':id') && path.match(/^\/(citizen|ward|department)\/complaints\/[^/]+$/)))?.label || 'City Connect'
  const pushNotice = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 3600) }
  return <div className={`app ${theme === 'dark' ? 'theme-dark' : ''}`}>
    {isDashboard ? <DashboardShell path={path} page={page} onNotice={pushNotice} theme={theme} onToggleTheme={toggleTheme} /> : <PublicShell path={path} onNotice={pushNotice} theme={theme} onToggleTheme={toggleTheme} />}
    {notice && <div className="toast"><CheckCircle2 size={18} />{notice}<button onClick={() => setNotice('')} aria-label="Dismiss notification"><X size={16}/></button></div>}
    <button className="mobile-menu-fab" onClick={() => setMobileOpen(!mobileOpen)} aria-label="Toggle navigation">{mobileOpen ? <X/> : <Menu/>}</button>
    {mobileOpen && <div className="mobile-nav-overlay" onClick={() => setMobileOpen(false)}><div className="mobile-nav" onClick={e => e.stopPropagation()}><button className="icon-button close-mobile" onClick={() => setMobileOpen(false)}><X/></button><Brand/><PublicLinks onNavigate={() => setMobileOpen(false)}/></div></div>}
  </div>
}
function Brand() { return <Link to="/" className="brand"><span className="brand-mark"><Landmark size={22}/></span><span><strong>city connect</strong><small>A complaint management platform</small></span></Link> }
function PublicLinks({ onNavigate }: { onNavigate?: () => void }) {
  return <nav className="public-links">
    <NavLink to="/" onClick={onNavigate}>Home</NavLink><a href="/#how-it-works" onClick={onNavigate}>How it works</a><NavLink to="/resolved-complaints" onClick={onNavigate}>Resolved cases</NavLink><NavLink to="/about" onClick={onNavigate}>About</NavLink><NavLink to="/track" onClick={onNavigate}>Track complaint</NavLink>
  </nav>
}
function PublicShell({ path, onNotice, theme, onToggleTheme }: { path: string; onNotice: (s: string) => void; theme: 'light' | 'dark'; onToggleTheme: () => void }) {
  return <><header className="public-header"><Brand/><PublicLinks/><div className="header-actions"><button className="theme-toggle" type="button" onClick={onToggleTheme} aria-label={`Switch to ${theme === 'light' ? 'dark' : 'light'} mode`} title={`Switch to ${theme === 'light' ? 'dark' : 'light'} mode`}>{theme === 'light' ? <Moon size={17}/> : <Sun size={17}/>}<span>{theme === 'light' ? 'Dark mode' : 'Light mode'}</span></button><Link className="login-link" to="/login">Log in</Link><Link className="button button-primary button-small" to="/complaints/new"><Plus size={16}/> Submit complaint</Link></div></header>
    <main>{path === '/' ? <HomePage/> : path === '/about' ? <AboutPage/> : path === '/complaints/new' ? <SubmitPage onNotice={onNotice}/> : path === '/track' ? <TrackPage onNotice={onNotice}/> : path === '/resolved-complaints' ? <ResolvedPage/> : path === '/login' ? <AuthPage mode="login" onNotice={onNotice}/> : path === '/register' ? <AuthPage mode="register" onNotice={onNotice}/> : <NotFound/>}</main>
    <PublicFooter/>
  </>
}
